<?php namespace App\Models;
final class Schedule extends BaseModel { public function forStudent(int $semesterId):array{return $this->all('SELECT sub.code,sub.name,c.name classroom,sc.day_of_week,sc.start_time,sc.end_time FROM schedules sc JOIN subjects sub ON sub.id=sc.subject_id LEFT JOIN classrooms c ON c.id=sc.classroom_id WHERE sub.semester_id=? ORDER BY FIELD(sc.day_of_week,\'Monday\',\'Tuesday\',\'Wednesday\',\'Thursday\',\'Friday\',\'Saturday\',\'Sunday\'),sc.start_time',[$semesterId]);} }
